window.addEventListener("DOMContentLoaded",(function(){const e=document.getElementById("filter"),s=document.getElementById("type").innerText;e.onkeyup=function(){const e=this.value.toLowerCase(),t=document.getElementsByClassName("item-card");if(e.length)switch(s){case"Login Credentials":for(const s of t)s.dataset.name.toLowerCase().includes(e)||s.dataset.service.toLowerCase().includes(e)?s.classList.remove("none"):s.classList.add("none");break;case"Payment Cards":for(const s of t)s.dataset.name.toLowerCase().includes(e)||s.dataset.number.toLowerCase().includes(e)||s.dataset.bank.toLowerCase().includes(e)?s.classList.remove("none"):s.classList.add("none");break;case"Security Notes":for(const s of t)s.dataset.title.toLowerCase().includes(e)?s.classList.remove("none"):s.classList.add("none");break}else for(const e of t)e.classList.remove("none")}}));